entries[452643] = { ["name"] = "Fransenfederhippogryph", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Fransenfederhippogryphen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Dieser majestätische Hippogryph stammt aus dem Fransenfederhochland von Feralas. Früher hat er seine Jungen beschützt, aber nun dient er einer größeren Sache.\"\nVerkäufer:\nBobadormu\nZone:\nTanaris\nKosten:\n5000\n\nVerkäufer:\nGrannadormu\nZone:\nTanaris\nKosten:\n5000" }
