entries[452868] = { ["name"] = "Blitzkette", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nBlitzkette\nEntfesselt bis zu 8 Sek. lang eine Woge aus Elektrizität auf einen 5-25 Meter entfernten Gegner. Beträgt die Distanz zwischen Euch und Eurem Ziel mehr als 30 Meter, wird er in Eure Richtung gezogen und verliert seine Leine." }
entries[452869] = { ["name"] = "Übertaktete S.E.L.F.I.E.-Kamera", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nAlways Malfunction (DNT)\nDiese Tüftelei wird immer eine Fehlfunktion haben. Wird zum Testen geteilter Fehlfunktionen verwendet.\n\nDieser Gegenstand überspringt die Logik zum Auswürfeln, ob eine Fehlfunktion auftritt, und testet nur die Effekte.\n\nWenn Ihr das hier seht, habt Ihr wahrscheinlich einen Platzhaltergegenstand vor Euch!" }
entries[452870] = { ["name"] = "Irdener Lieferbohrer", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nIrdener Lieferbohrer\nBeschwört einen irdenen Lieferbohrer, der nach verschiedenen Schlachtfeldstärkungen gräbt.\n\nDer Bohrer bleibt 28 Sek. lang aktiv und kann nur im Kampf beschworen werden. Sein Einsatz ist nur auf nicht gewerteten Schlachtfeldern und im Kriegsmodus auf Khaz Algar möglich." }
entries[452871] = { ["name"] = "Herzsuchender Gesundheitsinjektor", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nHerzsuchender Gesundheitsinjektor\nInjiziert eine medizinische Frostfeuerformel in Eure Adern, die Euch durch einen Frostschock sofort um 1943637 heilt. Zur Verhinderung einer plötzlichen Unterkühlung brennt Ihr anschließend für 30% des geheilten Betrags.\n\nTeilt sich eine Abklingzeit mit Heiltränken." }
