entries[452917] = { ["name"] = "Schicksalsgebundene Münze (Zahl)", ["text"] = "Sofort\nWirft immer, wenn ein Finishing-Move 5 oder mehr Combopunkte verbraucht, eine schicksalsgebundene Münze. Kopf erhöht den Schaden Eurer Angriffe 15 Sek. lang, oder bis Ihr Zahl werft, um 10%. Zahl fügt Eurem Ziel (210% der Angriffskraft) kosmischen Schaden zu.\n\nImmer wenn der Wurf das gleiche Ergebnis wie der vorherige Wurf hat, wird bei Kopf der Schaden um zusätzliche 2% und bei Zahl der Schaden um 10% erhöht." }
entries[452918] = { ["name"] = "Schutz des Lampenanzünders", ["text"] = "100 Meter Reichweite\nWirken in 1 sek. 20 sek. Abklingzeit\nSchützt das Ziel mit einem Schild, der den gesamten eingehenden Schaden um 10% verringert. Wenn das Ziel Schaden erleidet, wird es durch den Schild um 0% seiner maximalen Gesundheit geheilt.\n(1s Abklingzeit)" }
