entries[453203] = { ["name"] = "Luftröhre zerdrücken", ["text"] = "30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nBefiehlt dem Luchs, Euren Gegner anzuspringen und seine Luftröhre zu zerdrücken, was ihn für 15 Sek. zum Schweigen bringt und von der Flucht abhält." }
entries[453205] = { ["name"] = "Trankbombe der Macht", ["text"] = "40 Meter Reichweite\nSofort 5 min Abklingzeit\nWerft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der deren Primärwert 30 Sek. lang um ( 44 / 5) erhöht.\n\nVon der Explosion erfasste Gegner erleiden 255 Feuerschaden, der zwischen ihnen aufgeteilt wird." }
entries[453206] = { ["name"] = "Schattenumschlingung", ["text"] = "Unbegrenzte Reichweite\nSofort\n[ Seelendieb : 'Seelendieb' / 'Schattenblitz'] wendet 'Schattenumschlingung' an, was Euren dem Ziel zugefügten Schaden 16 Sek. lang um [ Seelendieb : 2% / 4%] erhöht. Bis zu [ Seelendieb : 4 / 2]-mal stapelbar." }
entries[453207] = { ["name"] = "Gezündete Lunte", ["text"] = "100 Meter Reichweite\nSofort\nBeim Verbrauchen von 'Kampfeshitze' besteht eine Chance von 6%, Euch 'Gezündete Lunte' zu gewähren.\n\nGezündete Lunte :\nEuer nächster Einsatz von 'Feuerschlag' macht bis zu 1 Ziel in der Nähe zu lebenden Bomben, die nach 2 Sek. explodieren und dem Ziel (26.8% der Zaubermacht) Feuerschaden sowie allen anderen Gegnern innerhalb von 10 Metern verringerten Schaden zufügen.\n\nBis zu 3 Gegner, die von der Explosion getroffen wurden, werden ebenfalls zu lebenden Bomben. Dieser Effekt kann sich aber nicht weiter ausbreiten." }
