entries[453211] = { ["name"] = "Anhaltende Ausdünstungen", ["text"] = "100 Meter Reichweite\nSofort\nFüttert das Koagulum und leitet 20% sämtlicher hervorgerufener Heilung um bis ( 10669 * 40 / 100) Heilung aufgezehrt wurde. Ist es gesättigt, bricht das Koagulum auf und heilt 5 Verbündete um [Quellwert] Gesundheit.\n\nAnhaltende Ausdünstungen lassen die nächsten Angriffe betroffener Verbündeter basierend auf der überschüssigen Heilung durch das Koagulum 76 zusätzlichen Schattenschaden verursachen.", ["unresolvedValues"] = true }
entries[453212] = { ["name"] = "Obsidianstrahl", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nSchattenkrone schleudert dunkle Energie auf ihr aktuelles Ziel und fügt ihm 9697798 Schattenschaden sowie allen anderen Spielercharakteren 2424450 zusätzlichen Schattenschaden zu.\n\nSchattenmagie strahlt 7 Sek. lang in anvisierte Richtungen und verursacht bei Kontakt 4848899 Schattenschaden und 9 Sek. lang alle 1 Sek. 1212225 zusätzlichen Schattenschaden. Dieser Effekt ist stapelbar." }
