entries[453310] = { ["name"] = "Obsidianstrahl", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchattenkrone schleudert dunkle Energie auf ihr aktuelles Ziel und fügt ihm 9697798 Schattenschaden sowie allen anderen Spielercharakteren 2424450 zusätzlichen Schattenschaden zu.\n\nSchattenmagie strahlt 7 Sek. lang in anvisierte Richtungen und verursacht bei Kontakt 4848899 Schattenschaden und 9 Sek. lang alle 1 Sek. 1212225 zusätzlichen Schattenschaden. Dieser Effekt ist stapelbar." }
