entries[453326] = { ["name"] = "Arkane Woge", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nVerbraucht Euer gesamtes aktuelles Mana, um Euer gegnerisches Ziel und Gegner in der Nähe zu vernichten und ihnen abhängig vom verbrauchten Mana bis zu [(520% der Zaubermacht) * 2] Arkanschaden zuzufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nFür die nächsten 15 Sek. ist Eure Manaregeneration um 425% und Euer Zauberschaden um 35% erhöht." }
entries[453327] = { ["name"] = "Kämpferische Weisheit", ["text"] = "Sofort\nAußerhalb des Kampfs pendelt sich Euer Chi auf 2 ein, anstatt erschöpft zu werden.\n\nAlle 15 Sek. setzt Euer nächster Einsatz von 'Tigerklaue' zusätzlich 'Schadensumleitung' ein und verursacht 30% mehr Schaden.\n\nSchadensumleitung\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]" }
entries[453328] = { ["name"] = "Kämpferische Weisheit", ["text"] = "Sofort\nAußerhalb des Kampfs pendelt sich Euer Chi auf 2 ein, anstatt erschöpft zu werden.\n\nAlle 15 Sek. setzt Euer nächster Einsatz von 'Tigerklaue' zusätzlich 'Schadensumleitung' ein und verursacht 30% mehr Schaden.\n\nSchadensumleitung\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]" }
