entries[453377] = { ["name"] = "Anhaltende Ausdünstungen", ["text"] = "100 Meter Reichweite\nSofort\nFüttert das Koagulum und leitet 20% sämtlicher hervorgerufener Heilung um bis ( 10669 * 40 / 100) Heilung aufgezehrt wurde. Ist es gesättigt, bricht das Koagulum auf und heilt 5 Verbündete um [Quellwert] Gesundheit.\n\nAnhaltende Ausdünstungen lassen die nächsten Angriffe betroffener Verbündeter basierend auf der überschüssigen Heilung durch das Koagulum 76 zusätzlichen Schattenschaden verursachen.", ["unresolvedValues"] = true }
entries[453381] = { ["name"] = "Erosionspolierte Steintafel", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nManchmal ist ein Stein einfach nur ein Stein. Es gibt aber auch ästhetisch sehr ansprechende Steine, deren Untersuchung sich lohnt! Es dürfte niemanden überraschen, dass es auf und unter Khaz Algar jede Menge Steine zu finden gibt, von denen einige zur Verbesserung von Abbauverfahren ihrer neuen Besitzer geeignet sein könnten.\n\nIhr dürft diese Woche noch 5 Exemplar(e) entdecken." }
