entries[453413] = { ["name"] = "Arkane Seele", ["text"] = "Sofort\n[ Feuer : Das Verbrauchen von 'Bürde der Macht' lässt Euren nächsten Einsatz von 'Feuerschlag' bis zu 2 zusätzliche Ziele treffen und einen Schauer von 4 Meteoriten auf das Ziel herabregnen.\n\nJeder Meteoriteneinschlag verringert die Abklingzeit von 'Feuerschlag' um 2.0 Sek /\n\nArkan\nDas Verbrauchen von 'Bürde der Macht' lässt Euren nächsten Einsatz von 'Arkanbeschuss' 20% mehr Schaden verursachen, 4 Arkane Aufladungen erzeugen und einen Schauer von 4 Meteoriten auf Euer Ziel herabregnen ]" }
