entries[453567] = { ["name"] = "Verdammnis", ["text"] = "100 Meter Reichweite\nSofort\nBelegt das Ziel mit drohender Verdammnis, was sofort (104.406% der Zaubermacht) Schattenschaden verursacht und nach 20 Sek. Gegnern innerhalb von 10 Metern (290.928% der Zaubermacht) Schattenschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nDas verzehren eines 'Dämonischen Kerns' verringert die Dauer von 'Verdammnis' um 3 Sek." }
entries[453568] = { ["name"] = "Pakt der Ered'ruin", ["text"] = "Wenn 'Verdammnis' ausläuft, besteht eine Chance, dass Ihr eine Verdammniswache beschwört, die 5-mal 'Verdammnisblitz' einsetzt, bevor sie wieder verschwindet. Jeder 'Verdammnisblitz' verursacht (298.327% der Zaubermacht) Schattenschaden." }
entries[453572] = { ["name"] = "Beledars Segen", ["text"] = "Ca. 1.21 Procs pro Minute\nBeim Erleiden von Schaden besteht eine Chance, dass ' Beledars Segen ' gewährt wird, was 15 Sek. lang die Vielseitigkeit um 823 erhöht.\n\nWenn Ihr Euch einem verbündeten Gruppenmitglied bis auf 3 Meter annähert, wird auch ihm ein Anteil von ' Beledars Segen ' gewährt und Ihr profitiert für die verbleibende Dauer beide vom Effekt." }
entries[453573] = { ["name"] = "Entziehendes Stilett", ["text"] = "Ca. 1.21 Procs pro Minute\nEure Schadenszauber und -fähigkeiten haben eine Chance, Euch 441 Gesundheit zu entziehen und 3 Sek. lang in die Leere zu werfen.\n\nBei ihrer Rückkehr fügt Ihr zufälligen Gegnern innerhalb von 30 Metern ( 1 * 957 ) Schaden zu.\n\nDies ist eine nerubische Verzierung." }
entries[453575] = { ["name"] = "Aszendenz", ["text"] = "Sofort\nErhaltet alle 8 Sek. ' Aszendenz ', während Ihr im Kampf seid.\n\n' Aszendenz ' erhöht 15 Sek. lang einen zufälligen Sekundärwert um 89 , bis zu 10-mal stapelbar.\n\nDies ist eine nerubische Verzierung." }
