entries[453599] = { ["name"] = "Arkane Entkräftung", ["text"] = "100 Meter Reichweite\nSofort\nWenn 'Freizaubern' verbraucht wird, wird der Zauberschaden 20 Sek. lang um 2% erhöht. Bis zu einem Wert von 10% stapelbar." }
entries[453600] = { ["name"] = "Äthereinstimmung", ["text"] = "Bei jedem 3. Verbrauch von 'Freizaubern' wird 'Äthereinstimmung' gewährt.\n\nÄthereinstimmung :\nEuer nächster Einsatz von 'Arkane Geschosse' fügt Eurem Primärziel 100% mehr Schaden zu und feuert auf bis zu 4 Gegner in der Nähe, um 50% mehr Schaden zu verursachen." }
entries[453601] = { ["name"] = "Äthereinstimmung", ["text"] = "Sofort\nNachdem Ihr 3-mal 'Freizaubern' verbraucht habt, verbrauchen Eure nächsten Einsätze von 'Arkane Geschosse' 'Arkane Batterie', wodurch Ihr Eurem Primärziel 150% mehr Schaden zufügt und auf bis zu 4 Gegner in der Nähe schießt und ihnen 100% mehr Schaden zufügt." }
