entries[453607] = { ["name"] = "Abyssischer Schlag", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nShurrai schlägt mit einem nekromantisch geladenen Anker auf sein aktuelles Ziel ein, fügt ihm 2788264 Seuchenschaden zu und belegt es mit einer Heilungsabsorption in Höhe des nicht mitigierten Schadens." }
entries[453608] = { ["name"] = "Verflüssigen", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek injiziert ihrem aktuelles Ziel Verdauungssäfte, fügt ihm 20147103 Naturschaden und 11512630 körperlichen Schaden.\n\nDiese Injektion verursacht 30 Sek. lang alle 1 Sek. 2014710 zusätzlichen Naturschaden und lässt das Ziel 1000% mehr körperlichen Schaden erleiden.\n\nWenn Ansurek ihrem Ziel die Injektion verabreicht, läuft sie mit Gift über, was eine ' Säureexplosion ' auslöst." }
entries[453609] = { ["name"] = "Verflüssigen", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek injiziert ihrem aktuelles Ziel Verdauungssäfte, fügt ihm 20147103 Naturschaden und 11512630 körperlichen Schaden.\n\nDiese Injektion verursacht 30 Sek. lang alle 1 Sek. 2014710 zusätzlichen Naturschaden und lässt das Ziel 1000% mehr körperlichen Schaden erleiden.\n\nWenn Ansurek ihrem Ziel die Injektion verabreicht, läuft sie mit Gift über, was eine ' Säureexplosion ' auslöst." }
entries[453611] = { ["name"] = "Auslöschungsprotokoll", ["text"] = "Wirken in 2 sek.\nDer Zaubernde fährt seine Servos hoch, was seine Bewegungsgeschwindigkeit um 25 verringert. Er verfolgt sein Ziel und fügt ihm in einem Bereich von 6 Metern 4 Sek. lang alle 1 Sek. körperlichen Schaden zu." }
entries[453612] = { ["name"] = "Auslöschungsprotokoll", ["text"] = "10 Meter Reichweite\nSofort\nDer Zaubernde fährt seine Servos hoch, was seine Bewegungsgeschwindigkeit um 25 verringert. Er verfolgt sein Ziel und fügt ihm in einem Bereich von 6 Metern 4 Sek. lang alle 1 Sek. körperlichen Schaden zu." }
entries[453613] = { ["name"] = "Ein Weilchen bleiben", ["text"] = "Unbegrenzte Reichweite\nSofort\nSetzt Euch zu Euren Freunden und ruht Euch ein Weilchen aus." }
entries[453614] = { ["name"] = "Abyssischer Schlag", ["text"] = "Sofort\nShurrai schlägt mit einem nekromantisch geladenen Anker auf sein aktuelles Ziel ein, fügt ihm 2788264 Seuchenschaden zu und belegt es mit einer Heilungsabsorption in Höhe des nicht mitigierten Schadens." }
entries[453615] = { ["name"] = "Verdünntes Toxin" }
entries[453616] = { ["name"] = "Verdammnisblitz", ["text"] = "20 Energie 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Schattenblitz auf den Gegner und verursacht (298.327% der Zaubermacht) Schattenschaden." }
entries[453617] = { ["name"] = "Übertakten", ["text"] = "Wirken in 3 sek.\nIncreases the caster's attack speed by 50% for 10 Sek..\nIncreases the movement speed of the caster by 50% for 10 Sek.." }
entries[453618] = { ["name"] = "Abyssischer Schlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nShurrai schlägt mit einem nekromantisch geladenen Anker auf sein aktuelles Ziel ein, fügt ihm 80 Seuchenschaden zu und belegt es mit einer Heilungsabsorption in Höhe des nicht mitigierten Schadens." }
entries[453619] = { ["name"] = "Schattenberührt", ["text"] = "'Tückischer Schlund' lässt das Ziel 20% zusätzlichen Schaden durch Eure Dämonen erleiden." }
entries[453620] = { ["name"] = "Leere" }
entries[453621] = { ["name"] = "Kerze in Haustiergröße", ["text"] = "Sofort 10 min Abklingzeit\nSetzt einem Haustier eine Kerze auf den Kopf. Die Kerze gibt etwas Wärme ab, die vorübergehend zur Zubereitung von Mahlzeiten genutzt werden kann." }
entries[453623] = { ["name"] = "Mönchsklassenset, Braumeister, 11.0, 2 Teile", ["text"] = "'Blackout-Tritt' und 'Fasshieb' verursachen 20% zusätzlichen Schaden. 'Beinarbeit' verringert den erlittenen Schaden außerdem um 3%." }
entries[453624] = { ["name"] = "Mönchsklassenset, Braumeister, 11.0, 4 Teile", ["text"] = "'Blackout-Tritt' erhöht Euren verursachten Schaden 15 Sek. lang um 1%, bis zu 3-mal stapelbar, und es besteht eine Chance, dass die Abklingzeit von 'Fasshieb' abgeschlossen wird und der nächste Einsatz keine Energie kostet." }
entries[453625] = { ["name"] = "Mönchsklassenset, Windläufer, 11.0, 4 Teile", ["text"] = "Eure anderen Nahkampffähigkeiten erhöhen den Schaden Eures nächsten Einsatzes von 'Tigerklaue' um 25%. Bis zu 6-mal stapelbar. 15% des durch 'Tigerklaue' verursachten Schadens wird Gegnern in der Nähe zugefügt. Schaden bei Zielen über 5 Ziele hinaus verringert.\n(800ms Abklingzeit)" }
entries[453626] = { ["name"] = "Mönchsklassenset, Windläufer, 11.0, 2 Teile", ["text"] = "'Tigerklaue' erhöht den Schaden Eurer nächsten Nahkampffähigkeit um 5.0%." }
entries[453627] = { ["name"] = "Mönchsklassenset, Nebelwirker, 11.0, 4 Teile", ["text"] = "'Beleben' verlängert die Dauer von 'Erneuernder Nebel' und 'Einhüllender Nebel' beim Primärziel um 3.0 Sek., bis zu 3.0 Sek." }
entries[453628] = { ["name"] = "Mönchsklassenset, Nebelwirker, 11.0, 2 Teile", ["text"] = "Erhöht die Heilung von 'Einhüllender Nebel' und 'Erneuernder Nebel' um 10%." }
entries[453629] = { ["name"] = "Todesritterklassenset, Blut, 11.0, 2 Teile", ["text"] = "Wenn Ihr eine oder mehr Aufladungen von 'Knochenschild' habt, erleidet Ihr 2.0% weniger Schaden. Wenn Ihr eine Aufladung von 'Knochenschild' verliert, besteht die Chance, dass Euer erlittener Schaden 6 Sek. lang um zusätzliche 1.0% verringert wird, bis maximal 3.0%." }
entries[453630] = { ["name"] = "Todesritterklassenset, Blut, 11.0, 4 Teile", ["text"] = "Euer Schaden ist pro aktiver Aufladung von 'Knochenschild' um 0.5% erhöht. Wenn Ihr mit weniger als 6 Aufladungen von 'Knochenschild' Schaden erleidet, besteht die Chance, dass 1 bis 2 Aufladungen von 'Knochenschild' erzeugt werden." }
entries[453631] = { ["name"] = "Todesritterklassenset, Frost, 11.0, 4 Teile", ["text"] = "Ca. 3 Procs pro Minute\nBeim Verbrauchen von Runenmacht besteht eine Chance, dass Eure Stärke 8 Sek. lang um 10% erhöht wird." }
entries[453632] = { ["name"] = "Todesritterklassenset, Unheilig, 11.0, 4 Teile", ["text"] = "Wenn Ihr einen Diener beschwört, wird Euer Tempo 8 Sek. lang um 1% erhöht, bis maximal 4%." }
entries[453633] = { ["name"] = "Todesritterklassenset, Unheilig, 11.0, 2 Teile", ["text"] = "Eure Diener verursachen 8% mehr Schaden." }
entries[453634] = { ["name"] = "Todesritterklassenset, Frost, 11.0, 2 Teile", ["text"] = "Eure Fähigkeiten, die Runenmacht verbrauchen, verursachen 8% erhöhten Schaden." }
entries[453636] = { ["name"] = "Kriegerklassenset, Waffen, 11.0, 2 Teile", ["text"] = "'Tödlicher Stoß' und 'Spalten' erhöhen den Schaden Eures nächsten Einsatzes von 'Überwältigen' um 10%." }
entries[453637] = { ["name"] = "Kriegerklassenset, Waffen, 11.0, 4 Teile", ["text"] = "Wird die Abklingzeit von 'Überwältigen' durch 'Taktiker' zurückgesetzt, wird der Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' oder 'Spalten' um 10% sowie die kritische Trefferchance um 10% erhöht. Dieser Effekt kann bis zu 2-mal gestapelt werden." }
entries[453638] = { ["name"] = "Kriegerklassenset, Furor, 11.0, 4 Teile", ["text"] = "Wenn 'Wütender Schlag' seine eigene Abklingzeit zurücksetzt, wird der Schaden Eures nächsten Einsatzes von 'Blutdurst' um 20% erhöht. Dieser Effekt kann bis zu 2-mal gestapelt werden." }
entries[453639] = { ["name"] = "Kriegerklassenset, Furor, 11.0, 2 Teile", ["text"] = "'Blutdurst' erhöht den Schaden Eures nächsten Einsatzes von 'Toben' um 15%." }
entries[453640] = { ["name"] = "Kriegerklassenset, Schutz, 11.0, 2 Teile", ["text"] = "Wenn die Abklingzeit von 'Schildschlag' durch 'Stratege' zurückgesetzt wird, erhaltet Ihr 'Strategieexperte', der 6 Sek. lang den Schaden von 'Schildschlag' um 5% erhöht und jeglichen erlittenen Schaden um 3% verringert." }
entries[453641] = { ["name"] = "Kriegerklassenset, Schutz, 11.0, 4 Teile", ["text"] = "Kritische Treffer von 'Schildschlag' erhöhen den Schaden, den 'Donnerknall' und 'Rache' verursachen, 8 Sek. lang um 10%." }
entries[453642] = { ["name"] = "Hexenmeisterklassenset, Gebrechen, 11.0, 4 Teile", ["text"] = "'Unheilvolle Euphorie' hat eine Chance, den verursachten Schaden Eurer 'Agonie', 'Verderbnis' und Eures 'Instabiles Gebrechen' 8 Sek. lang um 15% zu erhöhen." }
entries[453643] = { ["name"] = "Hexenmeisterklassenset, Gebrechen, 11.0, 2 Teile", ["text"] = "Schaden von 'Unheilvolle Euphorie' um 5% und seine kritische Trefferchance um 10% erhöht." }
entries[453644] = { ["name"] = "Hexenmeisterklassenset, Dämonologie, 11.0, 2 Teile", ["text"] = "Euer primärer Dämon verursacht 5% mehr Schaden und Euer 'Schattenblitz' verursacht 50% mehr Schaden." }
entries[453645] = { ["name"] = "Hexenmeisterklassenset, Dämonologie, 11.0, 4 Teile", ["text"] = "'Schattenblitz' hat eine Chance, Eure primäre Teufelswache wütend zu machen, was den Schaden ihres nächsten Einsatzes von 'Legionshieb' um 300% erhöht." }
entries[453646] = { ["name"] = "Hexenmeisterklassenset, Zerstörung, 11.0, 4 Teile", ["text"] = "Bei kritischen Treffern von 'Feuersbrunst' wird Euer Feuerschaden 6 Sek. lang um 5% erhöht." }
entries[453647] = { ["name"] = "Hexenmeisterklassenset, Zerstörung, 11.0, 2 Teile", ["text"] = "Kritische Trefferchance von 'Verbrennen' um 20% erhöht. Kritische Trefferchance von 'Feuersbrunst' um 25% erhöht." }
entries[453648] = { ["name"] = "Jägerklassenset, Treffsicherheit, 11.0, 2 Teile", ["text"] = "Erhöht den Schaden von 'Arkaner Schuss' und 'Mehrfachschuss' um 20%." }
entries[453650] = { ["name"] = "Jägerklassenset, Treffsicherheit, 11.0, 4 Teile", ["text"] = "Erhöht den Schaden von 'Gezielter Schuss' und 'Schnellfeuer' um 4%." }
entries[453651] = { ["name"] = "Jägerklassenset, Tierherrschaft, 11.0, 4 Teile", ["text"] = "Die Angriffe Eures Tiers haben eine Chance von 10%, Euren verursachten Begleiterschaden 10 Sek. lang um 10% zu erhöhen." }
entries[453652] = { ["name"] = "Jägerklassenset, Überleben, 11.0, 2 Teile", ["text"] = "Schaden von 'Lauffeuerbombe' um 8% erhöht." }
entries[453653] = { ["name"] = "Jägerklassenset, Überleben, 11.0, 4 Teile", ["text"] = "[ Mungobiss : 'Mungobiss' / 'Raptorstoß'] fügt Zielen, die von 'Lauffeuerbombe' betroffen sind, 20% mehr Schaden zu." }
entries[453654] = { ["name"] = "Jägerklassenset, Tierherrschaft, 11.0, 2 Teile", ["text"] = "'Stachelpfeil' erhöht das Angriffstempo Eures Tiers zusätzlich um 5%." }
entries[453655] = { ["name"] = "Paladinklassenset, Vergeltung, 11.0, 2 Teile", ["text"] = "Schaden von 'Klinge der Gerechtigkeit' ist um 15% erhöht, Schaden von 'Aschewelle' ist um 10% erhöht." }
entries[453656] = { ["name"] = "Paladinklassenset, Vergeltung, 11.0, 4 Teile", ["text"] = "'Aschewelle' erhöht Euren verursachten Schaden 8 Sek. lang um 8%." }
entries[453657] = { ["name"] = "Paladinklassenset, Schutz, 11.0, 2 Teile", ["text"] = "'Schild der Rechtschaffenen' verursacht 10% mehr Schaden und gewährt 3% Schadensreduktion." }
entries[453658] = { ["name"] = "Priesterklassenset, Heilig, 11.0, 2 Teile", ["text"] = "Heilung von 'Heiliger Schock' wird um 10% erhöht und seine Abklingzeit um 10% verringert." }
entries[453659] = { ["name"] = "Paladinklassenset, Heilig, 11.0, 4 Teile", ["text"] = "'Heiliger Schock' erhöht die anfängliche Heilung Eures nächsten Einsatzes von 'Wort der Herrlichkeit' oder 'Licht der Morgendämmerung' um 8% (bis zu 4 - mal stapelbar)." }
entries[453662] = { ["name"] = "Paladinklassenset, Schutz, 11.0, 4 Teile", ["text"] = "Der Einsatz einer Fähigkeit, die Heilige Kraft verbraucht, erhöht den verursachten Schaden und die verursachte Heilung bei Eurem nächsten Einsatz von 'Zornige Vergeltung' um 0.5%. Dieser Effekt ist stapelbar." }
entries[453664] = { ["name"] = "Druidenklassenset, Wächter, 11.0, 4 Teile", ["text"] = "Euer verursachter Arkanschaden ist um 5% erhöht. Euer verursachter Blutungsschaden ist um 8% erhöht." }
entries[453665] = { ["name"] = "Druidenklassenset, Wächter, 11.0, 2 Teile", ["text"] = "'Hauen' und 'Mondfeuer' erhöhen Euren verursachten Schaden und reduzieren Euren erlittenen Schaden 8 Sek. lang um 1% (3 - mal stapelbar).\n(700ms Abklingzeit)" }
entries[453666] = { ["name"] = "Druidenklassenset, Gleichgewicht, 11.0, 2 Teile", ["text"] = "Schaden von 'Sternensog' um 10% erhöht. Schaden von 'Sternenfall' um 14% erhöht." }
entries[453667] = { ["name"] = "Druidenklassenset, Gleichgewicht, 11.0, 4 Teile", ["text"] = "'Mondfinsternis' und 'Sonnenfinsternis' erhöhen jeweils die von 'Zorn' erzeugte Astrale Macht um 2 und die von 'Sternenfeuer' erzeugte Astrale Macht um 5." }
entries[453668] = { ["name"] = "Druidenklassenset, Wiederherstellung, 11.0, 4 Teile", ["text"] = "Eure Heilung wird 6 Sek. lang um 8% erhöht, wenn Ihr den Bonus von 'Seele des Waldes' verbraucht." }
entries[453669] = { ["name"] = "Druidenklassenset, Wiederherstellung, 11.0, 2 Teile", ["text"] = "Heilung von 'Nachwachsen', 'Wildwuchs' und 'Rasche Heilung' um 10% erhöht." }
entries[453670] = { ["name"] = "Druidenklassenset, Wildheit, 11.0, 2 Teile", ["text"] = "Euer 'Tigerfuror' erhöht 10 Sek. lang Eure Chance auf einen kritischen Treffer, angefangen bei 6% und alle 2 Sek. steigend um 1.0%." }
entries[453671] = { ["name"] = "Ruferklassenset, Verstärkung, 11.0, 4 Teile", ["text"] = "Solange 'Schwarzmacht' aktiv bleibt, erhöht es Primärwerte alle 2 Sek. um zusätzlich 0.4% Eures Werts, bis maximal 2.0%." }
entries[453672] = { ["name"] = "Ruferklassenset, Verstärkung, 11.0, 2 Teile", ["text"] = "'Emporstoßen' verursacht 15% mehr Schaden und erhöht den Schaden Eurer nächsten 2 Einsätze von 'Ausbruch' um 15%.\n(300ms Abklingzeit)" }
entries[453673] = { ["name"] = "Ruferklassenset, Bewahrung, 11.0, 2 Teile", ["text"] = "Erhöht die Heilung von 'Umkehrung' um 10% und die Fähigkeit hat eine Chance von 50%, 1 zusätzlichen Stapel von 'Temporalkomprimierung' zu gewähren." }
entries[453674] = { ["name"] = "Ruferklassenset, Bewahrung, 11.0, 4 Teile", ["text"] = "'Temporalkomprimierung' erhöht die Heilung Eures nächsten ermächtigten Zaubers um 5% pro Stapel." }
entries[453675] = { ["name"] = "Ruferklassenset, Verheerung, 11.0, 4 Teile", ["text"] = "Die Abklingzeiten von 'Ewigkeitswoge' und 'Zerschmetternder Stern' werden um 1.0 Sek. verringert und 'Ewigkeitswoge' gewährt jetzt 'Essenzexplosion'." }
entries[453676] = { ["name"] = "Ruferklassenset, Verheerung, 11.0, 2 Teile", ["text"] = "Schaden von 'Desintegration' um 6% und Schaden von 'Scheiterhaufen' um 6% erhöht." }
entries[453677] = { ["name"] = "Priesterklassenset, Heilig, 11.0, 2 Teile", ["text"] = "Glücksfall ist 10% effektiver." }
entries[453678] = { ["name"] = "Priesterklassenset, Heilig, 11.0, 4 Teile", ["text"] = "Heilung, Blitzheilung und Gebet der Heilung haben eine Chance von 50%, mit 35% Effektivität erneut zu wirken.\n(500ms Abklingzeit)" }
entries[453679] = { ["name"] = "Priesterklassenset, Disziplin, 11.0, 4 Teile", ["text"] = "'Pein' und 'Sühne' erhöhen den Schaden Eures nächsten Einsatzes von 'Gedankenschlag' um 25% oder die Absorption Eures nächsten Einsatzes von 'Machtwort: Schild' um 15% (bis zu 3 - mal)." }
entries[453680] = { ["name"] = "Priesterklassenset, Disziplin, 11.0, 2 Teile", ["text"] = "Heilung von 'Abbitte' wird um 5.0% erhöht." }
entries[453681] = { ["name"] = "Priesterklassenset, Schatten, 11.0, 2 Teile", ["text"] = "Die Dauer von 'Verschlingende Seuche' wird um 1.0 Sek. erhöht." }
entries[453682] = { ["name"] = "Priesterklassenset, Schatten, 11.0, 4 Teile", ["text"] = "'Verschlingende Seuche' erhöht Euren verursachten Schaden 10 Sek. lang um 2%. Mehrere Anwendungen können sich überschneiden." }
entries[453683] = { ["name"] = "Leerenschredder", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nKy'veza fügt ihrem aktuellen Ziel mehrere tiefe Schnittwunden zu. Jeder Treffer verursacht 5756315 körperlichen und 2878158 Schattenschaden und hinterlässt eine ' Kluftschnittwunde '." }
entries[453684] = { ["name"] = "Schamanenklassenset, Elementar, 11.0, 2 Teile", ["text"] = "Schaden von [ Elementarschlag : 'Elementarschlag' / 'Erdschock'] um 25% erhöht. Schaden von 'Erdbeben' um 25% erhöht." }
entries[453685] = { ["name"] = "Schamanenklassenset, Elementar, 11.0, 4 Teile", ["text"] = "Das Verbrauchen von Mahlstrom erhöht 5 Sek. lang Eure kritische Trefferchance um 5% und Euren verursachten kritischen Schaden um 10%." }
entries[453687] = { ["name"] = "Definitiver Mord" }
entries[453693] = { ["name"] = "Definitiver Mord", ["text"] = "Sofort\nDie Dunkelheit tötet ihr Ziel. Definitiv." }
entries[453699] = { ["name"] = "Flammenberührt", ["text"] = "Erhöht das Angriffstempo Eurer Schreckenspirscher um 10% und ihre kritische Trefferchance um 15%." }
entries[453701] = { ["name"] = "Leerenportal" }
entries[453704] = { ["name"] = "Wildheit von F'harg", ["text"] = "100 Meter Reichweite\nSofort\nErhöht das Angriffstempo Eurer Schreckenspirscher um 10% und ihre kritische Trefferchance um 15%." }
entries[453705] = { ["name"] = "Schamanenklassenset, Wiederherstellung, 11.0, 2 Teile", ["text"] = "'Flutwellen' erhöht die Heilung betroffener Zauber um 10%." }
entries[453706] = { ["name"] = "Schamanenklassenset, Wiederherstellung, 11.0, 4 Teile", ["text"] = "'Flutwellen' ist 80% effektiver und verringert die Manakosten betroffener Zauber um 8%." }
entries[453707] = { ["name"] = "Dämonenjägerklassenset, Rachsucht, 11.0, 2 Teile", ["text"] = "'Seelenspalter' verursacht 10% erhöhten Schaden und hat eine Chance von 25%, 1 geringe Seelenfragmente von einem getroffenen Ziel abzuspalten.\n(500ms Abklingzeit)" }
entries[453708] = { ["name"] = "Schamanenklassenset, Verstärkung, 11.0, 4 Teile", ["text"] = "Bei der Aktivierung von 'Wildgeist' wird 1 zusätzlicher Wildgeist beschworen." }
entries[453709] = { ["name"] = "Durchnässtes Schmettern", ["text"] = "20 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde schmettert auf den Boden, fügt Spielercharakteren in einem Umkreis von 15 Metern 30 Naturschaden zu und verlangsamt ihre Bewegungsgeschwindigkeit 12 Sek. lang um 30%." }
entries[453710] = { ["name"] = "Dämonenjägerklassenset, Rachsucht, 11.0, 4 Teile", ["text"] = "Der Verzehr eines Seelenfragments erhöht den Schaden und die Heilung Eurer nächsten Dämonischen Verwüstung um 2% (bis zu 30%)." }
entries[453711] = { ["name"] = "Dämonenjägerklassenset, Verwüstung, 11.0, 2 Teile" }
entries[453712] = { ["name"] = "Dämonenjägerklassenset, Verwüstung, 11.0, 4 Teile" }
entries[453713] = { ["name"] = "Schurkenklassenset, Meucheln, 11.0, 2 Teile", ["text"] = "Wenn Eure Blutungseffekte Schaden verursachen, besteht eine Chance, dass sie Euch 8 Sek. lang 'Abscheuliche Tinktur' gewähren, wodurch Euer Giftschaden pro Stapel um 1.0% erhöht wird (bis zu einem Maximum von 5 Stapeln).\n(Procchance: 25%)" }
entries[453714] = { ["name"] = "Schurkenklassenset, Meucheln, 11.0, 4 Teile", ["text"] = "Während Ihr 5 oder mehr Stapel von 'Abscheuliche Tinktur', 'Erdrosseln', 'Blutung' und 'Blutroter Sturm' habt, verursacht Ihr 10% mehr Schaden." }
entries[453715] = { ["name"] = "Schurkenklassenset, Gesetzlos, 11.0, 2 Teile", ["text"] = "'Finsterer Stoß', 'Pistolenschuss' und 'Hinterhalt' haben eine Chance von 35%, 'Astrales Toben' auszulösen, wodurch zusätzlich 30% Schattenschaden verursacht werden.\n(Procchance: 35%)" }
entries[453716] = { ["name"] = "Schurkenklassenset, Täuschung, 11.0, 2 Teile", ["text"] = "'Symbole des Todes' erhöht den Schaden Eurer nächsten 'Geheimtechnik' um 20%." }
entries[453717] = { ["name"] = "Schurkenklassenset, Täuschung, 11.0, 4 Teile", ["text"] = "'Geheimtechnik' erhöht den Schaden Eurer anderen Finishing-Moves 7 Sek. lang um 16%." }
entries[453718] = { ["name"] = "Schurkenklassenset, Gesetzlos, 11.0, 4 Teile", ["text"] = "'Astrales Toben' erhöht zusätzlich den Schaden Eures nächsten Einsatzes von 'Zwischen die Augen' um 15%. Bis zu 4-mal stapelbar." }
entries[453719] = { ["name"] = "Magierklassenset, Frost, 11.0, 2 Teile", ["text"] = "Schaden von 'Eislanze' um 8% erhöht." }
entries[453720] = { ["name"] = "Magierklassenset, Frost, 11.0, 4 Teile", ["text"] = "Wenn eine durch 'Eisige Finger' verbesserte 'Eislanze' Schaden verursacht, wird ein 'Eisiger Impuls' hervorgerufen, der Gegnern in der Nähe (30% der Zaubermacht) Frostschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[453721] = { ["name"] = "Magierklassenset, Feuer, 11.0, 4 Teile", ["text"] = "Nachdem 'Phönixflammen' Schaden verursacht haben, kehren sie mit einer Chance von 10% zu Euch zurück, um 1% ihrer Abklingzeit wiederherzustellen und Euch 10 Sek. lang 6% erhöhten Zauberschaden zu gewähren." }
entries[453722] = { ["name"] = "Magierklassenset, Feuer, 11.0, 2 Teile", ["text"] = "Schaden von Phönixflammen wird um 10% erhöht. Dieser Wert steigt für das Primärziel auf 25%." }
entries[453723] = { ["name"] = "Magierklassenset, Arkan, 11.0, 2 Teile", ["text"] = "Schaden von 'Arkanschlag' und 'Arkanbeschuss' um 6% erhöht." }
entries[453724] = { ["name"] = "Magierklassenset, Arkan, 11.0, 4 Teile", ["text"] = "'Arkane Kugel' und 'Arkane Geschosse' verursachen 10% mehr Schaden." }
entries[453726] = { ["name"] = "Wort der Vorherrschaft", ["text"] = "'Machtwort: Seelenstärke' gewährt Euch zusätzlich 5% Ausdauer." }
entries[453727] = { ["name"] = "Ewig brennende Zündung", ["text"] = "Wirken in 5 sek. 2 std. Wiederaufladung\n5 Aufladungen\nReagenzien:\nHändchen fürs Kunsthandwerk , Kristallines Pulver (5), Kernlegierung\nEntzieht der Schmiede die Restenergie, um sie später zu nutzen. Das Entzünden der Schmiede erhöht Eure Werte für die algarische Schmiedekunst basierend auf Eurer Immerflammenschmiede-Spezialisierung.\nBeruf:\n\nEwig brennende Zündung\nWird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Entzündet die Schmiede.\n\nErlangt für 10 Min. Genialität, Mehrfachherstellung und Einfallsreichtum basierend auf Eurer Immerflammenschmiede-Spezialisierung.\n\"Von Eurem Können mit der Schmiede gewonnen.\"" }
