entries[453868] = { ["name"] = "Aschewelle", ["text"] = "Sofort 30 sek. Abklingzeit\n1 Aufladung\nWirbelt in weitem Bogen herum, fügt allen Gegnern innerhalb von 14 Metern vor Euch (292.6% der Angriffskraft) Strahlenschaden zu, belegt sie mit ' Nachstrom der Wahrheit ', was sie brennen lässt und ihnen zusätzlich [(65.28% der Angriffskraft) * (2.73077)] Schaden im Verlauf von 9 Sek. zufügt.\n\nDämonen und Untote werden außerdem für 5 Sek. betäubt.\n\nErzeugt 3 Heilige Kraft." }
entries[453869] = { ["name"] = "Wuchernde Schatten", ["text"] = "Sofort\nDas Ritual des Ordens der Nacht auf Beledar fügt allen, die nicht durch ' Strahlendes Licht ' geschützt sind, 242444938 Schattenschaden zu, was bei Ablauf des Effekts zum sofortigen Tode führt." }
