entries[453871] = { ["name"] = "Rache des Ozeans", ["text"] = "Sofort\nWenn er stirbt, fügt der Zaubernde Spielercharakteren innerhalb von 6 Metern 174266 Seuchenschaden zu sowie 8 Sek. lang alle 2 Sek. zusätzlich 87133 Seuchenschaden. Dieser Effekt ist stapelbar.\n\nDie entfesselten Seelen wirken sich auch auf ihren Entführer aus und fügen Shurrai 5227995 Seuchenschaden zu." }
