entries[453874] = { ["name"] = "Blutblitz", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nFeuert ein Geschoss aus verderbtem Blut auf das Ziel ab und verursacht Schattenschaden." }
entries[453875] = { ["name"] = "Seelen hervorbringen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nShurrai speit 10 Sek. lang alle 2 Sek. die Seelen seiner früheren Opfer aus. Fügt allen Spielercharakteren 174266 Seuchenschaden zu und stößt eine Masse gefangener Seelen aus, die Spielercharakteren innerhalb von 8 Metern um den Einschlag 697066 Seuchenschaden zufügt. Jeder Einschlag beschwört 3 ertrunkene Arathi." }
