entries[453888] = { ["name"] = "Seide spinnen", ["text"] = "Sofort\nDer Zaubernde wirbelt 6 Sek. lang schnell mit Strängen exquisiten Gespinstes auf seine Gegner zu und fügt Gegnern in der Nähe alle 1 Sek. Naturschaden zu, um das Gespinst mit ihrem Blut einzufärben." }
