entries[453894] = { ["name"] = "Mitternachtsviolett", ["text"] = "Wirken in 2 sek.\nDer Zaubernde bedeckt sich mit einer alles verschlingenden violetten Farbe, was sein Tempo und seine Bewegungsgeschwindigkeit massiv erhöht." }
