entries[453906] = { ["name"] = "Riesenfußtritt", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nTritt einen Feind mit einem riesigen Fuß, fügt ihm körperlichen Schaden zu und unterbricht 2 Sek. lang sein Zauberwirken." }
entries[453908] = { ["name"] = "Dämonische Brutalität", ["text"] = "Kritische Treffer Eurer Zauber und Dämonen verursachen 6% mehr Schaden." }
