entries[453916] = { ["name"] = "Tod von unten", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nSikran ermächtigt seinen Speer mit kosmischer Energie und rammt ihn in den Boden, sodass Kopien davon unter Spielercharakteren hervorschießen, die Spielercharakteren innerhalb von 0 Metern 0 Schattenschaden zufügen. Der letzte Ausbruch hinterlässt lauernde Speere, die Spielercharakteren innerhalb von 0 Metern alle 2 Sek. 0 Schattenschaden zufügen." }
entries[453917] = { ["name"] = "Perfektionierte Form", ["text"] = "Schatten\nEuer verursachter Schaden ist um 12% erhöht, während 'Dunkler Aufstieg' aktiv ist, und um 20%, während die Leerengestalt aktiv ist.\n\nHeilig\nEure hervorgerufene Heilung ist um 10% erhöht, während 'Apotheose' aktiv ist." }
