entries[453920] = { ["name"] = "Kosmische Infusion", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 3 sek.)\nSikran kanalisiert kosmische Energie in eine nahe Waffe. Während des Vorgangs pulsiert er vor latenter Energie und verursacht 3 Sek. lang alle 1 Sek. 0 Schattenschaden." }
