entries[454001] = { ["name"] = "Anhaltende Kraft", ["text"] = "Heilig\nWenn ein 'Strahlenkranz' erzeugt wird, wird die Dauer von 'Apotheose' um 1 Sek. verlängert. Wenn 'Apotheose' nicht aktiv ist, werden bis zu 6 Sek. gespeichert.\n\nAußerhalb des Kampfes oder wenn Ihr von einem Kontrollverlusteffekt betroffen seid, wird die Dauer von 'Apotheose' für bis zu 20 Sek. pausiert.\n\nSchatten\nWenn ein 'Strahlenkranz' erzeugt wird, wird die Dauer von um 1 Sek. verlängert. Wenn nicht aktiv ist, werden bis zu 6 Sek. gespeichert.\n\nAußerhalb des Kampfes oder wenn Ihr von einem Kontrollverlusteffekt betroffen seid, wird die Dauer von für bis zu 20 Sek. pausiert." }
