entries[454006] = { ["name"] = "Verderbender Blick", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde kanalisiert dunkle Magie auf einen Gegner, die alle Gegner innerhalb von 4 Metern um dessen Position alle 1 Sek. mit ' Blutverderbnis ' belegt." }
entries[454007] = { ["name"] = "Blutverderbnis", ["text"] = "100 Meter Reichweite\nSofort\nVerursacht alle 1 Sek. Schattenschaden." }
entries[454008] = { ["name"] = "Blutnova", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nInflicts Shadow damage to all enemies within 100 yards." }
entries[454009] = { ["name"] = "Sturmgewitter", ["text"] = "Elementar\nNach dem Verbrauchen von 300 'Mahlstrom' wird Euer nächster Einsatz von 'Blitzschlag' durch 'Sturmgewitter' ersetzt.\n\nSturmgewitter 0.2% of base mana 40 Meter Reichweite Wirken in 2 Sek.\nRequires Shaman Ruft einen gewaltigen Blitzschlag herab, der Eurem Ziel (310.5% der Zaubermacht) Naturschaden und Gegnern innerhalb von 8 Metern um Euer Ziel [(310.5% der Zaubermacht) * 65 / 100] Naturschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nVerstärkung\nNach dem Verbrauchen von 40 Stapeln von 'Waffe des Mahlstroms' wird Euer nächster Einsatz von 'Blitzschlag' durch 'Sturmgewitter' ersetzt.\n\nSturmgewitter 0.2% of base mana 40 Meter Reichweite Wirken in 2 Sek.\nRequires Shaman Ruft einen gewaltigen Blitzschlag herab, der Eurem Ziel (310.5% der Zaubermacht) Naturschaden und Gegnern innerhalb von 8 Metern um Euer Ziel [(310.5% der Zaubermacht) * 65 / 100] Naturschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nVerstärkung\nConsumes Maelstrom Weapon for increased cast speed." }
